"""Generate docs/rules.md: every rule with severity, category, CWE, OWASP 2025 and ASVS 5.0."""

from __future__ import annotations

from pathlib import Path

from secscope.analysis.kb import KnowledgeBase

OUT = Path(__file__).resolve().parents[1] / "docs" / "rules.md"


def main() -> None:
    kb = KnowledgeBase.load()
    lines = [
        "# Rule catalogue",
        "",
        "Generated by `uv run python scripts/kb_table.py` from `remediation/*.yaml` — do not edit.",
        "",
        "| Rule | Title | Severity | Category | CWE | OWASP 2025 | ASVS 5.0 |",
        "|---|---|---|---|---|---|---|",
    ]
    for rule_id in sorted(kb.entries):
        e = kb.entries[rule_id]
        cwe = ", ".join(f"CWE-{c}" for c in e.cwe) or "–"
        lines.append(
            f"| `{rule_id}` | {e.title.en} | {e.severity} | {e.category.value} | {cwe} | "
            f"{', '.join(e.owasp) or '–'} | {', '.join(e.asvs) or '–'} |"
        )
    lines.append("")
    lines.append(f"{len(kb.entries)} rules.")
    OUT.write_text("\n".join(lines) + "\n", encoding="utf-8", newline="\n")
    print(f"wrote {OUT} ({len(kb.entries)} rules)")


if __name__ == "__main__":
    main()
